#!/usr/bin/env bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-10-24
#
# Tests for the artifact-pair helper (scripts/_shared/artifact.mjs, synced into
# create-plan, iterate-plan, create-research, iterate-research and
# review-artifact-comments). The layout it writes is the contract L2's
# auto-advance table reads (src/skills/create-plan/references/artifact-layout.md),
# so the file names, front matter and comment block are asserted exactly.
set -euo pipefail

HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
ROOT="$(cd "$HERE/../.." && pwd)"
A="$ROOT/scripts/_shared/artifact.mjs"

PASS=0; FAIL=0
ok()  { PASS=$((PASS+1)); echo "  ok: $1"; }
bad() { FAIL=$((FAIL+1)); echo "  FAIL: $1"; }

T="$(mktemp -d "${TMPDIR:-/tmp}/artifact-pairs.XXXXXX")"
trap 'rm -rf "$T"' EXIT
# mktemp keeps a doubled slash from a TMPDIR that ends in /; the helper resolves paths.
D="$(cd "$T" && pwd)/tasks"

[ -f "$A" ] && ok "helper exists" || { bad "helper missing at $A"; echo "Results: $PASS passed, $FAIL failed"; exit 1; }

fm() { node -e '
const t=require("fs").readFileSync(process.argv[1],"utf8"); const m=t.match(/^---\n([\s\S]*?)\n---\n/);
const k=process.argv[2]; const l=m && m[1].split("\n").find((x)=>x.startsWith(k+": "));
console.log(l ? l.slice(k.length+2) : "");' "$1" "$2"; }

# 1. create: NN prefix, kind and slug in the name, under <tasks>/<task>/
printf '# Research body one\n' > "$T/r1.md"
P1="$(node "$A" create --tasks-dir "$D" --task demo-task --kind research --slug hook-layout --title "Hook layout" --author lane-r --body "$T/r1.md")"
[ "$P1" = "$D/demo-task/01-research-hook-layout.md" ] && ok "first artifact is 01-research-hook-layout.md" || bad "first path: $P1"
printf '# Plan body one\n\nStep A.\n' > "$T/p1.md"
P2="$(node "$A" create --tasks-dir "$D" --task demo-task --kind plan --slug add-pairs --title "Add pairs" --author lane-x --body "$T/p1.md")"
[ "$P2" = "$D/demo-task/02-plan-add-pairs.md" ] && ok "next artifact takes the next NN (02)" || bad "second path: $P2"

# 2. front matter fields
[ "$(fm "$P2" ork_artifact)" = "1" ] && ok "ork_artifact: 1" || bad "ork_artifact missing"
[ "$(fm "$P2" kind)" = "plan" ] && [ "$(fm "$P2" task)" = "demo-task" ] && [ "$(fm "$P2" slug)" = "add-pairs" ] \
  && ok "kind, task, slug recorded" || bad "kind/task/slug wrong"
[ "$(fm "$P2" revision)" = "1" ] && [ "$(fm "$P2" status)" = "draft" ] && ok "revision 1, status draft" || bad "revision/status wrong"
[ -n "$(fm "$P2" created)" ] && [ "$(fm "$P2" created)" = "$(fm "$P2" updated)" ] && ok "created = updated on create" || bad "timestamps wrong"
grep -q '^<!-- ork:comments -->$' "$P2" && grep -q '^<!-- /ork:comments -->$' "$P2" && ok "empty comment block present" || bad "no comment block"
grep -q 'Step A.' "$P2" && ok "body written" || bad "body missing"

# 3. bad kind and bad slug are refused
RC=0; node "$A" create --tasks-dir "$D" --task demo-task --kind essay --slug x --body "$T/p1.md" >/dev/null 2>&1 || RC=$?
[ "$RC" -eq 2 ] && ok "unknown kind exits 2" || bad "unknown kind rc=$RC"
RC=0; node "$A" create --tasks-dir "$D" --task demo-task --kind plan --slug "Bad Slug" --body "$T/p1.md" >/dev/null 2>&1 || RC=$?
[ "$RC" -eq 2 ] && ok "non-kebab slug exits 2" || bad "bad slug rc=$RC"

# 4. comments: add, reply, list open
C1="$(node "$A" comment --file "$P2" --author Reviewer --quote "Step A." --text "Say which file step A touches.")"
C2="$(node "$A" comment --file "$P2" --author Reviewer --text "Add a rollback step.")"
[ "$C1" = "c1" ] && [ "$C2" = "c2" ] && ok "comment ids c1, c2" || bad "ids: $C1 $C2"
node "$A" reply --file "$P2" --id c1 --author Author --text "Will do."
OPEN="$(node "$A" list --file "$P2" --open --json)"
node -e 'const o=JSON.parse(process.argv[1]); process.exit(o.length===2 && o[0].quote==="Step A." && o[0].replies.length===1 ? 0 : 1)' "$OPEN" \
  && ok "list --open shows both with quote and reply" || bad "list wrong: $OPEN"

# 5. iterate keeps every earlier comment verbatim, bumps revision, replaces the body
BEFORE="$(sed -n '/^<!-- ork:comments -->$/,/^<!-- \/ork:comments -->$/p' "$P2")"
printf '# Plan body two\n\nStep A edits src/x.ts.\n\nRollback: revert the commit.\n' > "$T/p2.md"
node "$A" iterate --file "$P2" --body "$T/p2.md" >/dev/null
AFTER="$(sed -n '/^<!-- ork:comments -->$/,/^<!-- \/ork:comments -->$/p' "$P2")"
[ "$BEFORE" = "$AFTER" ] && ok "iterate keeps the comment block byte for byte" || bad "comment block changed by iterate"
[ "$(fm "$P2" revision)" = "2" ] && ok "iterate bumps revision to 2" || bad "revision after iterate: $(fm "$P2" revision)"
grep -q 'Rollback: revert' "$P2" && ! grep -q 'Plan body one' "$P2" && ok "iterate replaces the body" || bad "body not replaced"
[ "$(fm "$P2" created)" != "" ] && [ "$(fm "$P2" kind)" = "plan" ] && ok "iterate keeps the identity fields" || bad "identity fields lost"

# 6. iterate refuses a body that smuggles its own comment block (would duplicate or drop comments)
printf '# x\n<!-- ork:comments -->\n<!-- /ork:comments -->\n' > "$T/bad.md"
RC=0; node "$A" iterate --file "$P2" --body "$T/bad.md" >/dev/null 2>&1 || RC=$?
[ "$RC" -eq 2 ] && ok "body with a comment block is refused" || bad "smuggled block rc=$RC"
[ "$(fm "$P2" revision)" = "2" ] && ok "refused iterate leaves the file alone" || bad "refused iterate changed the file"

# 7. approve: a named approver and a reference are required, never while comments
#    are open, and never by the artifact's own author (L2 must not advance on a
#    lane approving itself; review comment c1 on the L6 plan).
[ "$(fm "$P2" author)" = "lane-x" ] && ok "author recorded on create" || bad "author missing: $(fm "$P2" author)"
RC=0; node "$A" approve --file "$P2" --by Reviewer --ref land-1 >/dev/null 2>&1 || RC=$?
[ "$RC" -eq 1 ] && ok "approve refused with 2 open comments" || bad "approve with open comments rc=$RC"
node "$A" resolve --file "$P2" --id c1 --author Author --text "Step A now names src/x.ts."
node "$A" resolve --file "$P2" --id c2 --author Author --text "Rollback added."
RC=0; node "$A" approve --file "$P2" >/dev/null 2>&1 || RC=$?
[ "$RC" -eq 2 ] && ok "approve without --by and --ref exits 2" || bad "approve with no approver rc=$RC"
RC=0; node "$A" approve --file "$P2" --by LANE-X --ref land-1 >/dev/null 2>&1 || RC=$?
[ "$RC" -eq 1 ] && [ "$(fm "$P2" status)" != "approved" ] && ok "self-approval by the author is refused" || bad "self-approval rc=$RC status=$(fm "$P2" status)"
node "$A" approve --file "$P2" --by Reviewer --ref land-1 >/dev/null && [ "$(fm "$P2" status)" = "approved" ] && ok "approve by a reviewer after resolving" || bad "approve failed"
[ "$(fm "$P2" approved_by)" = "Reviewer" ] && [ "$(fm "$P2" approved_ref)" = "land-1" ] && [ -n "$(fm "$P2" approved_at)" ] \
  && ok "approved_by, approved_ref, approved_at recorded" || bad "approval fields missing"
grep -q 'id="c1" author="Reviewer" status="resolved"' "$P2" && ok "resolved comment kept, status resolved" || bad "resolved comment not kept"

# 8. status: the L2 phase-done signal per artifact
S="$(node "$A" status --task-dir "$D/demo-task" --json)"
node -e '
const s=JSON.parse(process.argv[1]); const p=s.find((x)=>x.kind==="plan"); const r=s.find((x)=>x.kind==="research");
process.exit(s.length===2 && p.done===true && p.open_comments===0 && p.revision===2 && r.done===false && r.status==="draft" ? 0 : 1)' "$S" \
  && ok "status: plan done, research not done" || bad "status wrong: $S"

# 8b. iterating an approved artifact reopens it and drops the old approval
node "$A" iterate --file "$P2" --body "$T/p2.md" >/dev/null
[ "$(fm "$P2" status)" = "in-review" ] && [ -z "$(fm "$P2" approved_by)" ] && ok "iterate after approve: in-review, approval cleared" \
  || bad "approval survived an iterate: status=$(fm "$P2" status) by=$(fm "$P2" approved_by)"

# 9. a hand-edited open comment (reviewer typed it into the file) is read like a scripted one
cat >> "$T/hand.md" <<'EOF'
# Research body two
EOF
node "$A" iterate --file "$P1" --body "$T/hand.md" >/dev/null
node -e '
const fs=require("fs"); const p=process.argv[1]; let t=fs.readFileSync(p,"utf8");
t=t.replace("<!-- /ork:comments -->", "<comment id=\"c1\" author=\"Operator\" status=\"open\">\nCite the hook file.\n</comment>\n<!-- /ork:comments -->");
fs.writeFileSync(p,t);' "$P1"
N="$(node "$A" list --file "$P1" --open --json | node -e 'let s="";process.stdin.on("data",(d)=>s+=d).on("end",()=>console.log(JSON.parse(s).length))')"
[ "$N" = "1" ] && ok "hand-typed comment is listed as open" || bad "hand comment count: $N"

# 10. the approval gate fails closed: an open comment in a shape the parser
#     misreads must still block approve and keep status done=false (HOLD on
#     #4897, MUST 1). Each case gets its own artifact by lane-x, reviewed by reviewer-y.
gate_case() { # $1 slug, $2 JS that edits the file text t
  local p; p="$(node "$A" create --tasks-dir "$D" --task gate-task --kind plan --slug "$1" --author lane-x --body "$T/p1.md")"
  node -e 'const fs=require("fs"); const p=process.argv[1]; let t=fs.readFileSync(p,"utf8"); '"$2"'; fs.writeFileSync(p,t);' "$p"
  local rc=0; node "$A" approve --file "$p" --by reviewer-y --ref land-1 >/dev/null 2>&1 || rc=$?
  local done; done="$(node "$A" status --task-dir "$D/gate-task" --json | node -e 'let s="";process.stdin.on("data",(d)=>s+=d).on("end",()=>{const r=JSON.parse(s).find((x)=>x.slug===process.argv[1]); console.log(r ? r.done : "missing")})' "$1")"
  echo "$rc $(fm "$p" status) $done"
}
R="$(gate_case one-line 't=t.replace("<!-- /ork:comments -->", "<comment id=\"c1\" author=\"Operator\" status=\"open\">Cite the hook file.</comment>\n<!-- /ork:comments -->")')"
[ "$R" = "1 draft false" ] && ok "one-line hand-typed open comment blocks approve" || bad "one-line comment: rc status done = $R"
R="$(gate_case gt-author 't=t.replace("<!-- /ork:comments -->", "<comment id=\"c1\" author=\"ops > reviewer\" status=\"open\" at=\"2026-10-24T00:00:00Z\">\nCite the hook file.\n</comment>\n<!-- /ork:comments -->")')"
[ "$R" = "1 draft false" ] && ok "open comment with > in its author blocks approve" || bad "> in author: rc status done = $R"
R="$(gate_case crlf 't=t.replace("<!-- /ork:comments -->", "<comment id=\"c1\" author=\"Operator\" status=\"open\">\r\nCite the hook file.\r\n</comment>\r\n<!-- /ork:comments -->")')"
[ "$R" = "1 draft false" ] && ok "CRLF hand-typed open comment blocks approve" || bad "CRLF comment: rc status done = $R"
R="$(gate_case broken 't=t.replace("<!-- /ork:comments -->", "<comment id=\"c1\" status=\"open\"\nCite the hook file.\n<!-- /ork:comments -->")')"
[ "$R" = "1 draft false" ] && ok "an unreadable <comment opening blocks approve" || bad "unreadable comment: rc status done = $R"
# The writer must never emit an attribute value it cannot read back.
P3="$(node "$A" create --tasks-dir "$D" --task gate-task --kind plan --slug writer-gt --author lane-x --body "$T/p1.md")"
SUM_BEFORE="$(cksum < "$P3")"
RC=0; node "$A" comment --file "$P3" --author 'ops > reviewer' --text "Cite the hook file." >/dev/null 2>&1 || RC=$?
[ "$RC" -eq 2 ] && [ "$(cksum < "$P3")" = "$SUM_BEFORE" ] && ok "comment refuses an author with > and writes nothing" || bad "comment with > in author rc=$RC"

# 11. create requires --author, so the non-author check compares two real seat names
RC=0; node "$A" create --tasks-dir "$D" --task gate-task --kind plan --slug no-author --body "$T/p1.md" >/dev/null 2>&1 || RC=$?
[ "$RC" -eq 2 ] && ok "create without --author exits 2" || bad "create without --author rc=$RC"

# 12. a symlinked path to the helper still runs it (no silent exit 0)
mkdir -p "$T/real" && cp "$A" "$T/real/artifact.mjs" && ln -s "$T/real" "$T/link"
RC=0; node "$T/link/artifact.mjs" bogus >/dev/null 2>&1 || RC=$?
[ "$RC" -eq 2 ] && ok "unknown command through a symlinked path exits 2" || bad "symlinked path rc=$RC"

# 13. a string option with no value is a usage error (exit 2), never the value `true`
RC=0; node "$A" create --tasks-dir "$D" --task gate-task --kind plan --slug no-title --author lane-x --body "$T/p1.md" --title >/dev/null 2>&1 || RC=$?
[ "$RC" -eq 2 ] && [ -z "$(ls "$D/gate-task" | grep -- '-no-title.md')" ] && ok "--title with no value exits 2 and writes nothing" || bad "--title with no value rc=$RC"
RC=0; node "$A" create --task gate-task --kind plan --slug no-dir --author lane-x --body "$T/p1.md" --tasks-dir >/dev/null 2>&1 || RC=$?
[ "$RC" -eq 2 ] && ok "--tasks-dir with no value exits 2, not a stack trace" || bad "--tasks-dir with no value rc=$RC"

# 14. comment text is stored literally: $$, $& and $` are not replacement patterns
P4="$(node "$A" create --tasks-dir "$D" --task gate-task --kind plan --slug dollar --author lane-x --body "$T/p1.md")"
node "$A" comment --file "$P4" --author reviewer-y --text 'costs $$5, see $& and $` here' >/dev/null 2>&1
grep -qF 'costs $$5, see $& and $` here' "$P4" && ok "comment text with \$ patterns is stored literally" || bad "comment text with \$ patterns was rewritten"

# 15. the writer refuses text it could not read back: a literal <comment in comment text
SUM_BEFORE="$(cksum < "$P4")"
RC=0; node "$A" comment --file "$P4" --author reviewer-y --text "the <comment tag needs an id" >/dev/null 2>&1 || RC=$?
[ "$RC" -eq 2 ] && [ "$(cksum < "$P4")" = "$SUM_BEFORE" ] && ok "comment refuses text with <comment and writes nothing" || bad "comment with <comment in text rc=$RC"

echo "Results: $PASS passed, $FAIL failed"
[ "$FAIL" -eq 0 ]
